import{_ as a,o as e,c as p,i as t}from"./app.97a355c7.js";const m=JSON.parse('{"title":"hackday \u53C2\u4E0E\u540E\u611F\u60F3","description":"","frontmatter":{},"headers":[],"relativePath":"pages/explore/share/hackday\u53C2\u4E0E\u540E\u611F\u60F3.md","lastUpdated":1787801701000}'),o={name:"pages/explore/share/hackday\u53C2\u4E0E\u540E\u611F\u60F3.md"},c=t('<h1 id="hackday-\u53C2\u4E0E\u540E\u611F\u60F3" tabindex="-1">hackday \u53C2\u4E0E\u540E\u611F\u60F3 <a class="header-anchor" href="#hackday-\u53C2\u4E0E\u540E\u611F\u60F3" aria-hidden="true">#</a></h1><p>\u5148\u8BF4\u7ED3\u679C, \u8FD9\u6B21 hackday \u6D3B\u52A8\u6CA1\u6709\u5F97\u5956, \u6709\u70B9\u610F\u6599\u4E4B\u5916, \u4E5F\u6709\u4E00\u70B9\u70B9\u610F\u6599\u4E4B\u4E2D\u5427, \u60C5\u7EEA\u8FD8\u662F\u6BD4\u8F83\u5931\u843D\u7684.</p><p>\u9996\u5148\u8BF4\u610F\u6599\u4E4B\u5916, \u6211\u81EA\u5DF1\u662F\u89C9\u5F97\u6211\u505A\u7684\u8FD9\u4E2A\u4E1C\u897F(\u8F6F\u786C\u4EF6\u7ED3\u5408)\u662F\u6709\u65B0\u610F, \u6709\u843D\u5730\u573A\u666F\u7684, \u53E6\u5916\u5728\u4E00\u4F17\u4EA7\u54C1\u4E2D\u8FD9\u662F\u552F\u4E00\u4E00\u4E2A\u624B\u6413\u7684\u786C\u4EF6, \u4EA7\u54C1\u540E\u671F\u7684\u89C4\u5212(\u4EBA + \u4E16\u754C\u6A21\u578B\u7F51\u5173 + \u5177\u8EAB\u667A\u80FD + \u667A\u80FD\u5BB6\u5C45)\u4E5F\u66F4\u6709\u60F3\u8C61\u529B, \u6240\u4EE5\u6211\u89C9\u5F97\u600E\u4E48\u6837\u4E5F\u80FD\u5F97\u5230\u4E00\u4E2A\u6700\u4F73\u5355\u4EBA\u5956. \u4F46\u4E8B\u4E0E\u613F\u8FDD, \u4EC0\u4E48\u7ED3\u679C\u90FD\u6CA1\u6709, \u8FD8\u662F\u6709\u633A\u5927\u5931\u671B\u7684, \u4E0D\u8FC7\u6211\u81EA\u5DF1\u4E5F\u4E0D\u4F1A\u653E\u5F03\u8FD9\u4E2A\u4EA7\u54C1, \u76EE\u524D\u6B63\u5728\u505A PCB \u6253\u677F, \u6211\u8FD8\u662F\u60F3\u628A\u81EA\u5DF1\u7B2C\u4E00\u4E2A\u786C\u4EF6\u4EA7\u54C1\u641E\u51FA\u6765.</p><p>\u73B0\u5728\u8BF4\u4E00\u70B9\u70B9\u610F\u6599\u4E4B\u5185, \u6211\u81EA\u5DF1\u89C9\u5F97\u662F\u6211\u6CA1\u6709\u8BB2\u8FF0\u597D\u6211\u7684\u60F3\u6CD5\u4E0E\u4EA7\u54C1. \u5F00\u59CB\u6211\u5199\u4E86\u4E00\u6BB5\u6F14\u8BB2\u5185\u5BB9, \u5177\u4F53\u5982\u4E0B:</p><blockquote><p>\u5927\u5BB6\u4E0B\u5348\u597D, \u6211\u662F\u95F0\u571F, \u961F\u4F0D\u540D\u79F0\u7761\u4E2A\u597D\u89C9. \u987E\u540D\u601D\u4E49\u9879\u76EE\u662F\u4EE5\u7761\u7720\u4E3A\u5207\u5165\u53E3\u6765\u505A\u7684, \u4F46\u662F\u9879\u76EE\u4E0D\u81F3\u6B62\u4E8E\u7761\u7720\u573A\u666F, \u800C\u662F\u4E00\u4E2A\u89E3\u51B3\u65B9\u6848. \u5148\u770B\u6F14\u793A, \u4F20\u611F\u5668\u68C0\u6D4B\u5230\u5BA4\u5185\u4E8C\u6C27\u5316\u78B3\u6D53\u5EA6\u5347\u9AD8, \u81EA\u52A8\u8C03\u6574\u901A\u98CE, \u9664\u4E86\u73B0\u5728\u770B\u8D77\u6765\u8C8C\u4F3C\u666E\u901A\u7684\u667A\u80FD\u5BB6\u5C45, \u8FD8\u6709\u4E00\u4E2A\u524D\u7F6E\u7684\u5BA4\u5185\u4EFF\u771F. \u6BD4\u5982\u57FA\u4E8E kjl \u6237\u578B\u6570\u636E\u8FDB\u884C\u5BA4\u5185\u4EFF\u771F\u6A21\u62DF, \u5148\u770B\u4E0B\u653E\u54EA\u91CC\u6548\u679C\u4F1A\u66F4\u597D\u4E00\u4E9B.</p><p>\u8FD9\u4E2A\u9879\u76EE\u540E\u671F\u5B8C\u5168\u53EF\u4EE5\u52A0\u5165\u6C34\u7535\u6696\u901A, \u7F51\u7EDC\u62D3\u6251\u7B49, \u4E0D\u4F46\u65B0\u623F\u80FD\u7528, \u65E7\u623F\u6539\u9020, \u4E2A\u4EBA\u642D\u5EFA\u667A\u80FD\u5BB6\u5C45HomeAssistant\u4E5F\u80FD\u7528. \u8FD8\u53EF\u4EE5\u7528\u4E8E\u5927\u578B\u573A\u9986\u6D88\u9632/\u5B89\u5168\u76F8\u5173, \u53D1\u5C55\u65B9\u5411\u5F88\u591A. \u53E6\u5916\u6211\u4EEC\u79BB\u5BA2\u6237\u66F4\u8FD1, \u8FD8\u6709\u5B8C\u5584\u7684kjl \u6237\u578B\u6570\u636E, \u4E30\u5BCC\u7684\u5927\u5BB6\u5C45\u751F\u6001, \u8FD9\u4E9B\u5C31\u662F\u6211\u4EEC\u53EF\u4EE5\u6DF1\u5165\u5F00\u62D3\u7684\u62A4\u57CE\u6CB3. \u4ECE\u524D\u7F6E\u4EFF\u771F\u5230\u540E\u7F6E\u667A\u80FD\u5BB6\u5C45, \u662F\u4E00\u4E2A\u5B8C\u6574\u7684\u89E3\u51B3\u65B9\u6848. \u603B\u7ED3\u6765\u8BF4, \u786C\u4EF6\u7684\u5F00\u62D3, \u662F\u516C\u53F8\u4E00\u4E2A\u53EF\u884C\u7684\u53D1\u5C55\u65B9\u5411.</p><p>\u53E6\u5916, \u9879\u76EE\u8FD8\u6709\u8FDC\u671F\u5C55\u671B, \u53EF\u843D\u5730\u7684\u7A7A\u95F4\u667A\u80FD.</p><p>\u5148\u8BF4\u4E0B\u6211\u7406\u89E3\u7684\u7A7A\u95F4\u667A\u80FD\u5E02\u573A: \u771F\u5B9E\u6570\u636E + SP \u6A21\u578B\u4E2D\u67A2 + \u667A\u80FD\u5BB6\u5C45 + \u5177\u8EAB\u667A\u80FD. \u771F\u5B9E\u6570\u636E\u63D0\u4F9B\u4EFF\u771F\u6A21\u62DF, \u786E\u4FDD\u65B9\u6848\u53EF\u884C; SP \u6A21\u578B\u4E2D\u67A2\u4F5C\u4E3A\u7F51\u5173, \u8BA1\u7B97\u5206\u6790\u7A7A\u95F4\u6570\u636E, \u8FDB\u884C\u6267\u884C\u5224\u65AD\u4E0E\u51B3\u7B56, \u6307\u5BFC\u667A\u80FD\u5BB6\u5C45\u5F62\u6210\u667A\u80FD\u7684\u843D\u5730; \u667A\u80FD\u5BB6\u5C45\u662F\u5B9E\u9645\u843D\u5730, \u540C\u65F6\u4E5F\u662F SP \u6A21\u578B\u4E2D\u67A2\u7684&quot;MCP&quot;\u7CFB\u7EDF, \u5B8C\u6210\u5927\u6A21\u578B\u60F3\u8981\u7684\u5177\u4F53\u64CD\u4F5C; \u5177\u8EAB\u667A\u80FD\u5728\u5176\u4E2D\u8D77\u5230\u7BA1\u5BB6\u670D\u52A1, \u4E0D\u662F\u72EC\u7ACB\u4E2A\u4F53, \u800C\u662F\u5206\u6563\u7684\u96C6\u5408, \u4E0D\u9700\u8981\u4EC0\u4E48\u4E8B\u60C5\u90FD\u4EB2\u529B\u4EB2\u4E3A, \u53EA\u505A\u539F\u5B50\u6027\u4E8B\u7269\u5C31\u884C.</p><p>\u4E00\u4E2A\u6211\u60F3\u8C61\u7684\u573A\u666F:</p><p>\u56DE\u5230\u5BB6\u6D17\u6FA1, \u8863\u670D\u76F4\u63A5\u6254\u5728\u6D17\u6FA1\u95F4, \u5F00\u59CB\u6D17\u6FA1, \u8863\u670D\u81EA\u52A8\u9001\u5230\u6D17\u8863\u673A, \u6D17\u6FA1\u7684\u540C\u65F6\u5206\u62E3\u8863\u670D, \u6D17\u8863\u670D; \u81EA\u52A8\u628A\u7761\u8863\u4F20\u9012\u5230\u6D17\u6FA1\u95F4. \u6D17\u5B8C\u6FA1, \u4EBA\u7A7F\u4E0A\u8863\u670D\u5C31\u4EC0\u4E48\u90FD\u4E0D\u7528\u7BA1\u4E86; \u8863\u670D\u6D17\u597D\u540E, \u81EA\u52A8\u667E\u51FA\u6765; \u5DE5\u4F5C\u6D41\u7ED3\u675F. \u7B2C\u4E8C\u5929\u8863\u670D\u5E72\u4E86\u540E\u81EA\u52A8\u6536\u7EB3. \u8FD9\u4E2A\u8FC7\u7A0B\u4E2D\u5C31\u662F\u4EBA + \u7A7A\u95F4\u6A21\u578B + \u667A\u80FD\u5BB6\u5177 + \u5177\u8EAB\u667A\u80FD\u7684\u65E0\u611F\u8054\u52A8.</p><p>\u53E6\u4E00\u4E2A\u5C55\u89C8\u573A\u666F (\u8FD9\u6BB5\u662F\u6CA1\u6709\u6765\u5F97\u53CA\u6F14\u8BB2\u7684, \u6211\u662F\u60F3\u628A hackday \u5176\u4ED6\u7EC4\u76F2\u4EBA\u5F15\u5BFC\u548C\u673A\u5668\u72D7\u56CA\u62EC\u8FDB\u6765\u7684\u4E00\u4E2A\u573A\u666F)</p><p>\u8BBE\u8BA1\u5DE5\u5382\u4E4B\u524D\u505A\u8FC7\u4E00\u4E2A\u5BFC\u89C8\u673A\u5668\u4EBA, \u5F53\u65F6\u6B63\u597D\u5728\u65C1\u8FB9\u8C03\u8BD5, \u770B\u4E86\u4E0B\u8DEF\u7EBF\u4EC0\u4E48\u7684\u90FD\u9700\u8981\u5F55\u5165\u7136\u540E\u8C03\u6574, \u5F88\u9EBB\u70E6. \u4E00\u4E2A\u6709\u60F3\u8C61\u529B\u7684\u573A\u666F\u662F: \u673A\u5668\u4EBA\u5728\u524D\u9762\u5F15\u5BFC, \u5230\u4E86\u95E8\u524D, \u81EA\u52A8\u5F00\u95E8, \u5F15\u5BFC\u8FDB\u4F1A\u8BAE\u5BA4, \u544A\u8BC9\u5BA2\u6237\u524D\u65B9\u5DE6\u8F6C, \u8DDD\u79BB\u591A\u8FDC, \u5230\u4E86\u4F1A\u8BAE\u5BA4\u540E\u81EA\u52A8\u5F00\u542F\u5C4F\u5E55, \u7A7A\u8C03, \u8C03\u6574\u706F\u5149, \u8336\u996E\u8D44\u6599\u51C6\u5907. \u8FD9\u4E2A\u573A\u666F\u7684\u80CC\u540E\u5C31\u662F: SP \u6A21\u578B\u7A7A\u95F4\u80FD\u529B + \u76F2\u4EBA\u6307\u5F15\u9879\u76EE + \u6237\u578B\u6570\u636E + \u667A\u80FD\u5BB6\u5C45.</p></blockquote><p>\u56E0\u4E3A\u6BCF\u4E2A\u961F\u4F0D\u53EA\u6709 7 \u5206\u949F\u7684\u65F6\u95F4, \u65F6\u95F4\u6BD4\u8F83\u7D27\u5F20, \u6211\u5C31\u60F3\u7740\u63A7\u5236\u65F6\u95F4, \u8BA1\u5212\u524D\u9762\u5148\u653E\u4E2A demo \u89C6\u9891\u7684\u5F00\u5934, \u7136\u540E\u628A\u89C6\u9891\u9759\u97F3, \u6211\u628A\u4E0A\u9762\u8FD9\u4E00\u6BB5\u8BDD\u6F14\u8BB2\u5B8C, \u8FD9\u6837\u65F6\u95F4\u80FD\u63A7\u5236\u5230 3-4 \u5206\u949F\u5DE6\u53F3, \u540E\u9762\u80FD\u7559\u4E00\u4E9B\u65F6\u95F4\u7528\u4E8E\u63D0\u95EE. \u8BA1\u5212\u7684\u633A\u597D, \u4F46\u662F\u771F\u7684\u4E0A\u573A\u540E, \u6211\u53D1\u73B0\u6211\u8FD8\u662F\u5361\u58F3\u6709\u70B9\u5389\u5BB3, \u9884\u60F3\u7684\u8131\u7A3F\u6CA1\u6709\u5B9E\u73B0, \u6CA1\u6709\u5B8C\u6574\u64AD\u653E\u5B8C\u89C6\u9891, \u6574\u4F53\u8282\u594F\u5F88\u4E71, \u6CA1\u6709\u5145\u5206\u5C55\u793A\u6574\u4E2A\u9879\u76EE, \u4E5F\u6CA1\u6709\u5C55\u793A\u81EA\u5DF1\u7684\u9762\u5305\u677F\u548C\u786C\u4EF6, \u6709\u70B9\u4E00\u584C\u7CCA\u6D82\u7684\u611F\u89C9. \u9664\u4E86\u8FD9\u4E9B\u4E3B\u89C2\u5931\u8BEF, \u6211\u81EA\u5DF1\u6F14\u8BB2\u7684\u65F6\u95F4\u4E5F\u5F88\u9760\u540E, \u4ECE\u4E0B\u5348\u4E24\u70B9\u4E00\u76F4\u5230 6 \u70B9 15 \u5DE6\u53F3\u624D\u8F6E\u5230\u6211, \u65F6\u95F4\u8DE8\u5EA6\u5927, \u8BC4\u59D4\u4E5F\u6CA1\u90A3\u4E48\u591A\u7CBE\u529B, \u4E0D\u8FC7\u8FD9\u90E8\u5206\u5F71\u54CD\u56E0\u7D20\u5360\u6BD4\u5F88\u5C0F. \u8FD8\u6709\u4E00\u4E2A\u5C31\u662F\u5230\u6211\u6F14\u8BB2\u7684\u65F6\u5019\u4E3B\u6301\u4EBA\u628A\u53F3\u4E0A\u89D2\u7684\u5012\u8BA1\u65F6\u5173\u4E86, \u5C31\u5BFC\u81F4\u5BF9\u65F6\u95F4\u4E0D\u591F\u654F\u611F, \u4E5F\u7B97\u662F\u5F88\u5C0F\u7684\u4E00\u4E2A\u5F71\u54CD\u56E0\u7D20\u5427.</p><p>\u90A3\u7ECF\u5386\u8FD9\u6B21\u610F\u6599\u4E4B\u5916\u540E, \u6211\u81EA\u5DF1\u7684\u53CD\u601D\u662F\u4EC0\u4E48\u5462?</p><ol><li>\u4E4B\u524D\u603B\u8BA4\u4E3A\u4E00\u4E2A\u4EBA\u80FD\u505A\u51FA\u6765, \u5C31\u6CA1\u5FC5\u8981\u4E24\u4E2A\u4EBA, \u73B0\u5728\u89C9\u5F97\u8FD8\u662F\u9700\u8981\u627E\u4E00\u4E2A\u80FD\u5145\u5206\u5C55\u793A\u9879\u76EE\u6784\u601D\u7684\u961F\u53CB, \u53D1\u6325\u5404\u81EA\u7684\u4F18\u52BF, \u6BD4\u5982\u505A\u4E1C\u897F\u548C\u6F14\u8BB2, \u534F\u4F5C\u5171\u8D62;</li><li>\u81EA\u5DF1\u60F3\u7684\u548C\u5B9E\u9645\u80FD\u505A\u5230\u7684\u662F\u6709\u5DEE\u8DDD\u7684, \u8BA1\u5212\u540E\u8981\u518D\u601D\u8003\u4E0B\u5B9E\u73B0\u7684\u5408\u7406\u6027, \u6BD4\u5982\u89C6\u9891\u9759\u97F3\u7684\u540C\u65F6\u6211\u518D\u53BB\u8BB2\u8BDD, \u90A3\u89C2\u4F17\u5173\u6CE8\u4EC0\u4E48\u5462? \u5927\u6982\u7387\u662F\u90FD\u88AB\u5F71\u54CD\u5230, \u9891\u7E41\u5207\u6362\u4E0A\u4E0B\u6587, \u5E94\u8BE5\u4E32\u884C;</li><li>\u953B\u70BC\u81EA\u5DF1\u7684\u4E0A\u573A\u6F14\u8BB2\u80FD\u529B, \u8FD9\u662F\u4E00\u4E2A\u8001\u6BDB\u75C5\u4E86, \u867D\u7136\u6211\u5185\u5FC3\u6DF1\u5904\u662F\u60F3\u4E0A\u53F0\u8BB2\u8BDD, \u5C55\u73B0\u81EA\u6211, \u4F46\u662F\u4E0A\u53F0\u540E\u603B\u662F\u4F1A\u58F0\u97F3\u53D1\u6296(\u8BB2\u4E00\u4F1A\u5C31\u6CA1\u4E86), \u6240\u4EE5\u8981\u5C3D\u91CF\u89E3\u51B3\u8FD9\u4E2A\u95EE\u9898. \u76EE\u524D\u65B9\u6848\u662F\u6BCF\u5929\u81EA\u5DF1\u5728\u5BB6\u5F55\u4E0B\u89C6\u9891, \u5728\u8BB0\u5F55\u81EA\u5DF1\u751F\u6D3B\u7684\u65F6\u5019\u953B\u70BC\u4E0B\u5728\u955C\u5934\u524D, \u5728\u6F14\u8BB2\u89C6\u89D2\u4E0B\u7684\u8BF4\u8BDD\u80FD\u529B.</li></ol><p>\u6700\u540E, \u7AD9\u5728\u6211\u81EA\u5DF1\u7684\u89D2\u5EA6\u4E0E\u601D\u60F3\u80CC\u666F\u4E0B, \u4E2A\u4EBA\u6B66\u65AD\u7684\u8BC4\u4EF7\u4E0B\u516C\u53F8\u83B7\u5956\u7684\u4F5C\u54C1\u4E0E\u5176\u4ED6\u672A\u83B7\u5956\u4F5C\u54C1.</p><p>\u5148\u8BF4\u83B7\u5956\u4F5C\u54C1, \u6211\u89C9\u5F97\u6CA1\u6709\u4E00\u4E2A\u8BA9\u4EBA\u773C\u524D\u4E00\u4EAE, \u4E24\u4E2A\u4E00\u7B49\u5956\u4E00\u4E2A\u662F\u673A\u5668\u72D7 + \u8F68\u8FF9\u8BC6\u522B, \u4E00\u4E2A\u662F\u5BA4\u5185\u7A7A\u95F4\u8DEF\u5F84\u5F15\u5BFC\u4ECB\u7ECD. \u524D\u8005\u8FD9\u4E0D\u662F\u54EA\u5BB6\u516C\u53F8\u6295\u94B1\u5C31\u80FD\u641E\u51FA\u6765? \u6709\u4EC0\u4E48\u65B0\u610F? \u540E\u8005\u8DEF\u5F84\u5F15\u5BFC, \u6211\u662F\u89C9\u5F97\u6CA1\u4EC0\u4E48\u5927\u7684\u53D1\u5C55\u7A7A\u95F4, \u62D8\u6CE5\u4E8E\u4E00\u4E2A\u5F88\u7EC6\u5206\u7684\u5BA2\u7FA4: \u9AD8\u51C0\u503C\u4E14\u8BB2\u7A76\u7684\u7528\u6237. \u9664\u4E86\u4E00\u7B49\u5956\u540E, \u5269\u4E0B\u83B7\u5956\u7684\u8981\u4E48\u662F\u6587\u65C5\u5C0F\u6E38\u620F, \u7C97\u5236\u6EE5\u9020\u7684\u6E38\u620F\u5E73\u53F0, \u8C01\u73A9\u6E38\u620F\u73A9\u4F60\u8FD9\u79CD\u554A? \u6E38\u620F\u5382\u5546\u5F04\u7D20\u6750\u4E5F\u4E0D\u4F1A\u8981\u554A. \u8981\u4E48\u5C31\u662F\u4E00\u4E9B\u6982\u5FF5\u4EA7\u54C1, \u5185\u90E8\u4E0D\u77E5\u9053\u5E72\u5565\u7528\u7684\u9879\u76EE, \u54E6, \u6F0F\u4E86\u4E00\u4E2A, \u6709\u4E00\u4E2A\u505A\u4EA7\u54C1 3D \u5B89\u88C5\u89C6\u9891\u7684\u9879\u76EE, \u8FD9\u4E2A\u6211\u89C9\u5F97\u633A\u597D\u7684, \u503C\u5F97\u83B7\u5956, \u5176\u4ED6\u7684\u5B8C\u5168\u6CA1\u6709\u4EAE\u70B9.</p><p>\u5176\u4ED6\u672A\u83B7\u5956\u4F5C\u54C1, \u6211\u89C9\u5F97\u6709\u4E00\u4E2A\u5F88\u597D\u7684\u662F\u76F2\u4EBA\u5F15\u5BFC\u9879\u76EE. \u5373\u5229\u7528\u6A21\u578B\u7684\u7A7A\u95F4\u8BC6\u522B\u80FD\u529B\u5224\u65AD\u76F2\u4EBA\u773C\u524D, \u5934\u9876, \u811A\u4E0B\u7684\u969C\u788D\u7269, \u5F15\u5BFC\u76F2\u4EBA\u524D\u884C. \u8FD9\u4E2A\u662F\u5F88\u6709\u4EBA\u6587\u5173\u6000, \u793E\u4F1A\u8D23\u4EFB\u4E0E\u521B\u65B0\u7684\u9879\u76EE, \u800C\u4E14\u76F2\u4EBA\u6D88\u8D39\u4E5F\u8FD8\u662F\u6709\u5E02\u573A\u7684. \u4E4B\u524D\u53BB\u76F2\u4EBA\u6309\u6469, \u5C31\u597D\u5947\u4ED6\u4EEC\u600E\u4E48\u7528\u667A\u80FD\u624B\u673A, \u95EE\u4E86\u540E\u624D\u53D1\u73B0\u4ED6\u4EEC\u662F\u8981\u4E70\u8F6F\u4EF6, \u6309\u6708\u6309\u5E74\u4ED8\u8D39\u7684. \u53E6\u5916\u8FD9\u4E2A\u9879\u76EE\u5982\u679C\u7528\u7684\u4EBA\u591A\u4E86\u540E, \u8FD9\u4E9B\u6570\u636E\u90FD\u662F\u5B9D\u8D35\u7684\u8D22\u5BCC. \u540C\u65F6\u8FD9\u4E2A\u80FD\u529B\u5728\u519B\u4E8B, \u8425\u6551, \u706B\u573A, \u96E8\u5929\u7B49\u6B63\u5E38\u4EBA\u89C6\u89C9\u53D7\u9650\u7684\u573A\u666F, \u4E5F\u53EF\u4EE5\u7A0D\u5FAE\u6269\u5C55\u4E0B. \u8FD9\u4E2A\u9879\u76EE\u6CA1\u6709\u83B7\u5F97\u6700\u4F73\u521B\u610F\u548C\u5546\u4E1A\u6F5C\u529B\u5956, \u6211\u89C9\u5F97\u5F88\u53EF\u60DC.</p><p>\u4E03\u4E03\u516B\u516B\u5DF2\u7ECF\u5199\u4E86\u8FD9\u4E48\u591A, \u6709\u70B9\u50CF\u4E00\u4E2A\u5931\u8D25\u8005\u7684\u65E0\u75C5\u547B\u541F, \u75C5\u5A07, \u4E0D\u8FC7\u5F88\u591A\u6210\u957F\u4E0E\u53CD\u601D\u4E5F\u90FD\u662F\u5728\u4E00\u4E2A\u4E2A\u5C0F\u4E11\u5F0F\u7684\u5C0F\u4F5C\u6587\u57FA\u7840\u4E0A\u6536\u83B7\u7684, \u4ECE\u73B0\u5728\u5F80\u540E\u770B, \u5386\u53F2\u7684\u81EA\u5DF1\u90FD\u50CF\u4E2A\u50BB\u5B50.</p><p>\u4F5C\u54C1\u89C6\u9891\u94FE\u63A5:</p><p><video controls width="100%" preload="metadata" src="https://qhstaticva-cos.kujiale.com/media/yun/help/college/1786799432554_\u57FA\u4E8EESP32\u7684\u5BA4\u5185\u7A7A\u6C14\u4EFF\u771F\u4E0E\u667A\u80FD\u8054\u52A8.mp4"></video></p>',14),s=[c];function d(_,r,i,l,h,n){return e(),p("div",null,s)}const u=a(o,[["render",d]]);export{m as __pageData,u as default};
